action.command:
curl -fsSL "https://api.github.com/repos/keycloak/keycloak/git/trees/26.1.2?recursive=0" 2>/dev/null | node -e "
let s='';process.stdin.on('data',d=>s+=d).on('end',()=>{
  const t=JSON.parse(s);
  console.log(t.tree.filter(x=>x.path.startsWith('themes')).slice(0,20).map(x=>x.path).join('\n'));
});" 2>&1 | head -25

